from pathlib import Path
import ast,json,subprocess,hashlib
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
p=json.loads(Path('proposal.json').read_text())
def validate(x,s,path='study'):
    kinds={'object':dict,'array':list,'string':str,'boolean':bool,'integer':int,'number':(int,float)}
    if 'type' in s:assert isinstance(x,kinds[s['type']]),(path,'type')
    if 'enum' in s:assert x in s['enum'],(path,'enum')
    if 'const' in s:assert x==s['const'],(path,'const')
    if isinstance(x,dict):
        assert set(s.get('required',[]))<=set(x),(path,'required')
        if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{})),(path,'extra keys')
        for k,v in x.items():
            if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
    if isinstance(x,list):
        assert len(x)>=s.get('minItems',0),(path,'minItems')
        for i,v in enumerate(x):validate(v,s.get('items',{}),path+f'[{i}]')
    if isinstance(x,str):assert len(x)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert p['parent_trial']==runtime['context']['incumbent']
assert set(p['study']['evidence_refs'])<=set(runtime['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
old=ast.parse(Path('history_g1_r0023_serial_symmetric.py').read_text())
old_classes=[n for n in old.body if isinstance(n,ast.ClassDef)];old_classes[-1].name='_SerialParentModel'
model_asts=[]
for v in p['variants']:
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    s=Path(v['file']).read_text();compile(s,v['file'],'exec');t=ast.parse(s)
    cfg=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
    assert cfg==v['config']
    assert hashlib.sha256(s.encode()).hexdigest() in v['note']
    cs=[n for n in t.body if isinstance(n,ast.ClassDef)]
    assert [ast.dump(n) for n in cs[:-1]]==[ast.dump(n) for n in old_classes]
    model_asts.append(ast.dump(cs[-1]))
assert len(set(model_asts))==1
# Count all statically declared diagnostic keys, expanding fixed literal loops.
model=cs[-1];method=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='diagnostics')
keys=[]
def visit(stmts,env):
    for n in stmts:
        if isinstance(n,ast.Assign):
            for target in n.targets:
                if isinstance(target,ast.Name) and target.id=='result' and isinstance(n.value,ast.Dict):
                    keys.extend(ast.literal_eval(k) for k in n.value.keys)
                elif isinstance(target,ast.Subscript) and isinstance(target.value,ast.Name) and target.value.id=='result':
                    keys.append(eval(compile(ast.Expression(target.slice),'key','eval'),{},env))
        elif isinstance(n,ast.For):
            # All loops with diagnostic writes have literal iterables.
            if not any(isinstance(a,ast.Subscript) and isinstance(a.value,ast.Name) and a.value.id=='result' and isinstance(a.ctx,ast.Store) for a in ast.walk(n)):continue
            items=eval(compile(ast.Expression(n.iter),'iter','eval'),{},env)
            for value in items:
                names=[n.target.id] if isinstance(n.target,ast.Name) else [a.id for a in n.target.elts]
                values=[value] if isinstance(n.target,ast.Name) else value
                visit(n.body,{**env,**dict(zip(names,values))})
        elif isinstance(n,ast.If):visit(n.body,env);visit(n.orelse,env)
visit(method.body,{})
assert len(keys)==len(set(keys)) and len(keys)<=64
assert len(keys)==52,(len(keys),keys)
industry={a['knowledge_id'] for a in p['knowledge_assessments'] if a['knowledge_id'].startswith('taac')}
assert set(runtime['context']['latest_knowledge_usage']['retrieved_ids'])-{'paper:din','paper:dmr'}<=industry
print('Study schema, evidence/protocol IDs, variant/config/source hashes and knowledge coverage pass.')
print('Three standalone modules compile; inherited class ASTs preserved; identical new Model AST.')
print('Diagnostics declare exactly %d unique scalar keys (limit64).'%len(keys))
print('Outputs: proposal.json, candidate.py, run_composition.py, run_zero.py.')
PY"

